// Treap node
typedef struct Node {
    int key;
    int priority;
    int size; // subtree size
    struct Node *left, *right;
} Node;

// Generate random priority
int rand_priority() {
    static int seed = 123456789;
    seed = seed * 1103515245 + 12345;
    return (unsigned int)(seed >> 16) & 0x7FFF;
}

// Get size of a node (handles NULL)
int get_size(Node *node) {
    return node ? node->size : 0;
}

// Update size of a node
void update_size(Node *node) {
    if (node) {
        node->size = 1 + get_size(node->left) + get_size(node->right);
    }
}

// Split treap by key: left tree has keys < key, right tree has keys >= key
void split(Node *root, int key, Node **left, Node **right) {
    if (!root) {
        *left = *right = NULL;
        return;
    }
    if (root->key < key) {
        *left = root;
        split(root->right, key, &(root->right), right);
        update_size(root);
    } else {
        *right = root;
        split(root->left, key, left, &(root->left));
        update_size(root);
    }
}

// Merge two treaps (all keys in left < all keys in right)
Node* merge(Node *left, Node *right) {
    if (!left) return right;
    if (!right) return left;
    if (left->priority > right->priority) {
        left->right = merge(left->right, right);
        update_size(left);
        return left;
    } else {
        right->left = merge(left, right->left);
        update_size(right);
        return right;
    }
}

// Insert a key, return 1 if inserted, 0 if already exists
Node* insert(Node *root, int key, int *inserted) {
    Node *left, *mid, *right;
    split(root, key, &left, &mid);
    split(mid, key + 1, &mid, &right);
    if (mid) {
        // key already exists
        *inserted = 0;
        root = merge(merge(left, mid), right);
    } else {
        *inserted = 1;
        Node *new_node = (Node*)malloc(sizeof(Node));
        new_node->key = key;
        new_node->priority = rand_priority();
        new_node->size = 1;
        new_node->left = new_node->right = NULL;
        root = merge(merge(left, new_node), right);
    }
    return root;
}

// Delete a key, return 1 if deleted, 0 if not found
Node* delete(Node *root, int key, int *deleted) {
    Node *left, *mid, *right;
    split(root, key, &left, &mid);
    split(mid, key + 1, &mid, &right);
    if (mid) {
        *deleted = 1;
        free(mid);
    } else {
        *deleted = 0;
    }
    root = merge(left, right);
    return root;
}

// Find if key exists
int find(Node *root, int key) {
    while (root) {
        if (root->key == key) return 1;
        if (key < root->key) root = root->left;
        else root = root->right;
    }
    return 0;
}

// Dump keys in [L, R] in order using in-order traversal
void dump_range(Node *root, int L, int R, int *first) {
    if (!root) return;
    if (root->key >= L) dump_range(root->left, L, R, first);
    if (root->key >= L && root->key <= R) {
        if (!(*first)) printf(" ");
        printf("%d", root->key);
        *first = 0;
    }
    if (root->key <= R) dump_range(root->right, L, R, first);
}

