    struct Node *left, *right;
} Node;

Node *newNode(int key) {
    Node *n = (Node*)malloc(sizeof(Node));
    n->key = key;
    n->priority = rand();
    n->size = 1;
    n->left = n->right = NULL;
    return n;
}

int sz(Node *n) { return n ? n->size : 0; }
void update(Node *n) { if(n) n->size = 1 + sz(n->left) + sz(n->right); }

// Split into left (<= key) and right (> key)
void split(Node *n, int key, Node **l, Node **r) {
    if(!n) { *l = *r = NULL; return; }
    if(n->key <= key) {
        split(n->right, key, &n->right, r);
        *l = n;
    } else {
        split(n->left, key, l, &n->left);
        *r = n;
    }
    update(n);
}

Node* merge(Node *l, Node *r) {
    if(!l) return r;
    if(!r) return l;
    if(l->priority > r->priority) {
        l->right = merge(l->right, r);
        update(l);
        return l;
    } else {
        r->left = merge(l, r->left);
        update(r);
        return r;
    }
}

