static Node* new_node(int key) {
    Node *n = (Node*)malloc(sizeof(Node));
    n->key = key;
    n->pri = ((unsigned)rand() << 16) ^ (unsigned)rand();
    n->l = n->r = NULL;
    return n;
}

static void split(Node *t, int key, Node **a, Node **b) {
    if (!t) {
        *a = *b = NULL;
    } else if (t->key < key) {
        split(t->r, key, &t->r, b);
        *a = t;
    } else {
        split(t->l, key, a, &t->l);
        *b = t;
    }
}

static Node* merge(Node *a, Node *b) {
    if (!a) return b;
    if (!b) return a;
    if (a->pri > b->pri) {
        a->r = merge(a->r, b);
        return a;
    } else {
        b->l = merge(a, b->l);
        return b;
    }
}

static int find(Node *t, int key) {
    while (t) {
        if (key == t->key) return 1;
        t = (key < t->key) ? t->l : t->r;
    }
    return 0;
}

static int count_nodes(Node *t) {
    if (!t) return 0;
    return 1 + count_nodes(t->l) + count_nodes(t->r);
}

static void insert_key(int key) {
    if (find(root, key)) return;
    Node *a, *b;
    split(root, key, &a, &b);
    root = merge(merge(a, new_node(key)), b);
}

static void delete_key(int key) {
    Node *a, *b, *c;
    split(root, key, &a, &b);
    split(b, key + 1, &b, &c);
    if (b) free(b);
    root = merge(a, c);
}

static void dump_range(Node *t, int L, int R, int *first) {
    if (!t) return;
    if (t->key > L) dump_range(t->l, L, R, first);
    if (L <= t->key && t->key <= R) {
        if (!*first) printf(" ");
