import sys
import random

# Treap (randomized balanced BST) supporting:
# insert x
# find x
# delete x
# dump L R  -> all keys in [L, R] in ascending order

class Node:
    __slots__ = ("key", "prio", "left", "right", "size")
    def __init__(self, key):
        self.key = key
        self.prio = random.randint(1, 1 << 30)
        self.left = None
        self.right = None
        self.size = 1

def sz(t):
    return t.size if t else 0

def upd(t):
    if t:
        t.size = 1 + sz(t.left) + sz(t.right)

def rotate_right(t):
    x = t.left
    t.left = x.right
    x.right = t
    upd(t)
    upd(x)
    return x

def rotate_left(t):
    x = t.right
    t.right = x.left
    x.left = t
    upd(t)
    upd(x)
    return x

def find(t, key):
    while t:
        if key == t.key:
            return True
        t = t.left if key < t.key else t.right
    return False

def insert(t, key):
    if t is None:
        return Node(key), True
    if key == t.key:
        return t, False
    if key < t.key:
        t.left, ok = insert(t.left, key)
        if t.left and t.left.prio > t.prio:
            t = rotate_right(t)
    else:
        t.right, ok = insert(t.right, key)
        if t.right and t.right.prio > t.prio:
            t = rotate_left(t)
    upd(t)
    return t, ok

def delete(t, key):
    if t is None:
        return None, False
    if key < t.key:
        t.left, ok = delete(t.left, key)
        upd(t)
        return t, ok
    if key > t.key:
        t.right, ok = delete(t.right, key)
        upd(t)
        return t, ok

    # delete this node
    if t.left is None:
        return t.right, True
    if t.right is None:
        return t.left, True

    if t.left.prio > t.right.prio:
        t = rotate_right(t)
        t.right, ok = delete(t.right, key)
    else:
        t = rotate_left(t)
        t.left, ok = delete(t.left, key)
    upd(t)
    return t, ok

def dump_range(t, L, R, out):
    if t is None:
        return
    if t.key > L:
        dump_range(t.left, L, R, out)
    if L <= t.key <= R:
        out.append(str(t.key))
    if t.key < R:
        dump_range(t.right, L, R, out)

def main():
    data = sys.stdin.read().strip().splitlines()
    if not data:
        return

    root = None
    ans = []

    # Supports either:
    # 1) first line = number of queries
    # 2) all lines are queries
    start = 0
    if data[0].strip().isdigit() and len(data) >= 2:
        q = int(data[0].strip())
        if q <= len(data) - 1:
            start = 1

    for line in data[start:]:
        if not line.strip():
            continue
        parts = line.split()
        cmd = parts[0].lower()

        if cmd == "insert":
            x = int(parts[1])
            root, _ = insert(root, x)
            ans.append(str(sz(root)))
        elif cmd == "find":
            x = int(parts[1])
            ans.append("1" if find(root, x) else "0")
        elif cmd == "delete":
            x = int(parts[1])
            root, _ = delete(root, x)
        elif cmd == "dump":
            L = int(parts[1])
            R = int(parts[2])
            cur = []
            dump_range(root, L, R, cur)
            ans.append(" ".join(cur))

    sys.stdout.write("\n".join(ans))

if __name__ == "__main__":
    main()
